import Link from "next/link";
import { ArrowLeft, ClipboardCheck } from "lucide-react";
import { redirect } from "next/navigation";
import { saveVendorProfile } from "./actions";
import { FirebaseVendorProfileEditor } from "@/src/components/firebase-platform/vendor-profile-editor";
import { getRoleHome } from "@/src/lib/auth/routing";
import { requireUser } from "@/src/lib/auth/session";
import { isFirebaseOperationalBackend } from "@/src/lib/firebase/platform";
import { createSupabaseServerClient } from "@/src/lib/supabase/server";

const field="min-h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-base";
export default async function VendorProfilePage({searchParams}:{searchParams:Promise<{result?:string}>}){
  const user=await requireUser();const org=user.memberships.find(item=>item.organizationType==="vendor"&&["owner","admin"].includes(item.role));if(!org)redirect(getRoleHome(user));const result=(await searchParams).result;
  if(isFirebaseOperationalBackend())return <FirebaseVendorProfileEditor user={user} organization={org} result={result}/>;
  const supabase=await createSupabaseServerClient();const [{data:organization},{data:profile},{data:categories},{data:services},{data:areas}]=await Promise.all([supabase.from("organizations").select("name,phone,website_url").eq("id",org.organizationId).single(),supabase.from("vendor_profiles").select("description,public_email,approval_status,publication_status,public_display_consent").eq("organization_id",org.organizationId).single(),supabase.from("vendor_category_assignments").select("vendor_categories(name)").eq("vendor_organization_id",org.organizationId),supabase.from("vendor_service_offerings").select("vendor_services(name)").eq("vendor_organization_id",org.organizationId).eq("is_active",true),supabase.from("vendor_service_cities").select("cities(name,state_code)").eq("vendor_organization_id",org.organizationId).eq("is_active",true)]);
  const category=(categories?.[0]?.vendor_categories as unknown as {name:string}|null)?.name??"";const serviceText=(services??[]).map(item=>(item.vendor_services as unknown as {name:string}|null)?.name).filter(Boolean).join("\n");const areaText=(areas??[]).map(item=>{const city=item.cities as unknown as {name:string;state_code:string}|null;return city?`${city.name}, ${city.state_code}`:null;}).filter(Boolean).join("\n");
  return <div><Link href="/vendor" className="inline-flex items-center text-sm font-bold text-slate-500"><ArrowLeft className="mr-2 size-4"/>Vendor dashboard</Link><div className="mt-6 grid gap-6 lg:grid-cols-[1fr_18rem]"><main className="rounded-[2rem] border border-slate-200 bg-white p-6 sm:p-10"><h1 className="text-4xl font-semibold">Complete your marketplace profile.</h1>{result?<p className="mt-4 rounded-xl bg-emerald-50 p-3">Profile {result}.</p>:null}<form action={saveVendorProfile} className="mt-8 grid gap-5 sm:grid-cols-2"><label className="sm:col-span-2">Business name<input className={field} name="businessName" required defaultValue={organization?.name}/></label><label className="sm:col-span-2">Description<textarea className={`${field} min-h-32`} name="description" required minLength={40} defaultValue={profile?.description??""}/></label><label>Public email<input className={field} name="publicEmail" type="email" required defaultValue={profile?.public_email??user.email}/></label><label>Phone<input className={field} name="phone" required defaultValue={organization?.phone??""}/></label><label className="sm:col-span-2">Website<input className={field} name="website" defaultValue={organization?.website_url??""}/></label><label className="sm:col-span-2">Primary category<input className={field} name="primaryCategory" required defaultValue={category}/></label><label>Services<textarea className={`${field} min-h-32`} name="services" required defaultValue={serviceText}/></label><label>Service areas<textarea className={`${field} min-h-32`} name="serviceAreas" required defaultValue={areaText}/></label><label className="sm:col-span-2"><input name="publicDisplayConsent" type="checkbox" required defaultChecked={profile?.public_display_consent}/> Public-display consent</label><button className="min-h-12 rounded-full bg-slate-950 text-white sm:col-span-2">Save profile</button></form></main><aside className="rounded-2xl bg-slate-950 p-6 text-white"><ClipboardCheck className="size-6 text-emerald-400"/><p className="mt-5">Approval: {profile?.approval_status??"pending"}</p><p>Publication: {profile?.publication_status??"unpublished"}</p></aside></div></div>;
}
